INSERT INTO news (date, lang, title, text) VALUES
 ('2026-11-13', 'es', 'LAIKA 64 2.0', 'Videos de los juegos con sonido en todas las vistas, juego en línea con salas, chat, amigos y mensajes, descargas más rápidas y donaciones con criptomonedas.'),
 ('2026-11-13', 'en', 'LAIKA 64 2.0', 'Game videos with sound in every view, online play with rooms, chat, friends and messages, faster downloads and crypto donations.'),
 ('2026-11-13', 'pt', 'LAIKA 64 2.0', 'Vídeos dos jogos com som em todas as vistas, jogo online com salas, chat, amigos e mensagens, downloads mais rápidos e doações com criptomoedas.'),
 ('2026-11-13', 'fr', 'LAIKA 64 2.0', 'Vidéos des jeux avec le son dans toutes les vues, jeu en ligne avec salles, chat, amis et messages, téléchargements plus rapides et dons en crypto.'),
 ('2026-11-13', 'it', 'LAIKA 64 2.0', 'Video dei giochi con audio in tutte le viste, gioco online con stanze, chat, amici e messaggi, download più veloci e donazioni in cripto.'),
 ('2026-11-13', 'de', 'LAIKA 64 2.0', 'Spielvideos mit Ton in allen Ansichten, Online-Spiel mit Räumen, Chat, Freunden und Nachrichten, schnellere Downloads und Krypto-Spenden.'),
 ('2026-11-13', 'ru', 'LAIKA 64 2.0', 'Видео игр со звуком во всех видах, сетевая игра с комнатами, чатом, друзьями и сообщениями, более быстрые загрузки и пожертвования криптовалютой.'),
 ('2026-11-14', 'es', 'LAIKA 64 2.0.1 (próximamente)', 'Nuevo Jugar en línea en tres columnas: salas con portada, partidas en curso, chat y jugadores con bandera, ping y LAN o Wi-Fi. Salas de 2 a 4 jugadores y hasta 3 jugadores en una misma consola.'),
 ('2026-11-14', 'en', 'LAIKA 64 2.0.1 (coming soon)', 'New three-column Play online: rooms with their cover, games in progress, chat and players with flag, ping and LAN or Wi-Fi. Rooms for 2 to 4 players and up to 3 players on one console.'),
 ('2026-11-14', 'pt', 'LAIKA 64 2.0.1 (em breve)', 'Novo Jogar online em três colunas: salas com capa, partidas em andamento, chat e jogadores com bandeira, ping e LAN ou Wi-Fi. Salas de 2 a 4 jogadores e até 3 jogadores num mesmo console.'),
 ('2026-11-14', 'fr', 'LAIKA 64 2.0.1 (bientôt)', 'Nouveau Jeu en ligne en trois colonnes : salles avec jaquette, parties en cours, chat et joueurs avec drapeau, ping et LAN ou Wi-Fi. Salles de 2 à 4 joueurs et jusqu''à 3 joueurs sur une console.'),
 ('2026-11-14', 'it', 'LAIKA 64 2.0.1 (in arrivo)', 'Nuovo Gioco online in tre colonne: stanze con copertina, partite in corso, chat e giocatori con bandiera, ping e LAN o Wi-Fi. Stanze da 2 a 4 giocatori e fino a 3 giocatori su una console.'),
 ('2026-11-14', 'de', 'LAIKA 64 2.0.1 (demnächst)', 'Neues Online-Spiel in drei Spalten: Räume mit Cover, laufende Spiele, Chat und Spieler mit Flagge, Ping und LAN oder WLAN. Räume für 2 bis 4 Spieler und bis zu 3 Spieler an einer Konsole.'),
 ('2026-11-14', 'ru', 'LAIKA 64 2.0.1 (скоро)', 'Новая сетевая игра в три столбца: комнаты с обложкой, идущие игры, чат и игроки с флагом, пингом и LAN или Wi-Fi. Комнаты на 2-4 игроков и до 3 игроков на одной консоли.'),
 ('2026-11-14', 'es', 'Correcciones del juego en línea', 'Volver a la sala desde el menú de pausa, aviso cuando alguien entra a tu sala, mensajes rápidos traducidos, país automático, solo juegos compatibles al crear partida, sin salas fantasma ni jugadores repetidos y ping más exacto.'),
 ('2026-11-14', 'en', 'Online play fixes', 'Back to the room from the pause menu, an alert when someone joins your room, translated quick messages, automatic country, only compatible games when creating a game, no ghost rooms or repeated players and a more accurate ping.'),
 ('2026-11-14', 'pt', 'Correções do jogo online', 'Voltar à sala pelo menu de pausa, aviso quando alguém entra na sua sala, mensagens rápidas traduzidas, país automático, só jogos compatíveis ao criar partida, sem salas fantasma nem jogadores repetidos e ping mais exato.'),
 ('2026-11-14', 'fr', 'Corrections du jeu en ligne', 'Retour à la salle depuis le menu pause, alerte quand quelqu''un entre, messages rapides traduits, pays automatique, seulement les jeux compatibles à la création, plus de salles fantômes ni de joueurs en double, ping plus juste.'),
 ('2026-11-14', 'it', 'Correzioni del gioco online', 'Torna alla stanza dal menu di pausa, avviso quando qualcuno entra, messaggi rapidi tradotti, paese automatico, solo giochi compatibili nel creare la partita, niente stanze fantasma né giocatori doppi e ping più preciso.'),
 ('2026-11-14', 'de', 'Korrekturen am Online-Spiel', 'Zurück zum Raum im Pausenmenü, ein Signal wenn jemand beitritt, übersetzte Schnellnachrichten, automatisches Land, nur passende Spiele beim Erstellen, keine Geisterräume oder doppelten Spieler und genauerer Ping.'),
 ('2026-11-14', 'ru', 'Исправления сетевой игры', 'Возврат в комнату из меню паузы, сигнал при входе игрока, переведённые быстрые сообщения, автоматическая страна, только подходящие игры при создании, без комнат-призраков и повторов игроков, более точный пинг.');
